        additionalProperties: false,
      },
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job. Rejects missing jobs or repeated cancellation.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Identifier of the job to cancel.' },
        },
        required: ['job_id'],
        additionalProperties: false,
      },
    },
  ];
}

