    const { job_id } = args;
    if (typeof job_id !== 'string' || job_id.length === 0) {
      throw error('job_id is required and must be a non-empty string');
    }
    const existing = jobs.get(job_id);
    if (existing === 'running') {
      throw error(`job ${job_id} is already running`);
    }
    jobs.set(job_id, 'running');
    return result(`job ${job_id} running`);
  }

  if (name === 'cancel_job') {
    const { job_id } = args;
    if (typeof job_id !== 'string' || job_id.length === 0) {
      throw error('job_id is required and must be a non-empty string');
    }
    const existing = jobs.get(job_id);
    if (existing === undefined) {
      throw error(`job ${job_id} not found`);
    }
    if (existing === 'cancelled') {
      throw error(`job ${job_id} is already cancelled`);
    }
    jobs.set(job_id, 'cancelled');
    return result(`job ${job_id} cancelled`);
  }

  throw error(`unknown tool: ${name}`);
}
